insert into public.email_automations(id,key,name,trigger_type,is_active) values('70547a05-45c5-5e2d-92ed-21217d2420e4','course_month-freedom','Месяц свободы','course',false) on conflict(id) do nothing;
insert into public.courses(slug,title,kind,landing_url,access_days,day_card_extra_days,webinar_extra_days,automation_id,source_hash) values('month-freedom','Месяц свободы','practicum','',90,3,5,'70547a05-45c5-5e2d-92ed-21217d2420e4','b78bafe02165887308f3c6f6d6f32c08b5ce69cf4b8060793a7132e6a94e1238') on conflict(slug) do update set title=excluded.title,source_hash=excluded.source_hash;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('aa369f75-e047-535c-a433-9c5d8dcf9366','70547a05-45c5-5e2d-92ed-21217d2420e4','Урок 1',1,0,'{Месяц свободы} Добро пожаловать!','{"ru":"{Месяц свободы} Добро пожаловать!"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png" alt="Месяц свободы" width="504" height="146" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я рад, что вы решились в течение месяца направить внимание и целенаправленно поработать с такими прекрасными состояниями, как творчество, способность создавать поток и действовать в нём, видеть красоту, чувствовать вдохновение, иметь право самовыражаться, проявлять свою уникальность, самобытность, красиво коммунициривать во всех форматах (речь, музыка, рисунок... своё поведение...) - то есть речь о пятой чакре. Внимательно прочитайте это письмо, чтобы эффективно включиться в занятия.</p><p></p><p><strong>1. Расписание совместных практик</strong><br>Первый (вводный) урок уже доступен вам в Гармонизаторе на вкладке &quot;День&quot;. Чтобы его увидеть, при входе в Гармонизатор, укажите тот же ваш имейл, на который пришло данное письмо. Послезавтра вы получите второй урок - это будет наша первая совместная практика. Через неделю вам придёт вторая практика, ещё через неделю - третья, и через неделю - четвёртая. То есть в течение месяца, помимо вводного урока, вас ожидают четыре инереснейшие практики. Доступ к записям всех этих уроков сохранится у вас в течение трёх месяцев после окончания практикума. Тем не менее, я рекомендую вам проходить уроки не откладывая, так чтобы между практиками была неделя для внутренних трансформаций. Не увеличивайте интервалы между практиками, чтобы они не накапливались, как снежный ком. Наиболее эффективный темп занятий - одна практика в неделю. К тому-же имейте в виду, что первый урок посвящён тому, чтобы вы правильно сформулировали намерение на этот месяц, а также сами для себя определили небольшие дополнительные практики, которые будете выполнять каждый день в течение этого месяца.</p><p></p><p><strong>2. Техника безопасности</strong><br>Я забочусь о вашем здоровье и напоминаю, что только вы несёте ответственность за адекватность выполнения асан, пранаям и медитаций, вашим физическим возможностям и психическому состоянию. Важно понимать, что это онлайн занятия, и я не могу проконтролировать ваше состояние. Практикум ориентирован на людей со средним уровнем физической подготовки. Однако, у вам могут быть физические и психологические особенности. Пожалуйста, будьте внимательны к своему состоянию. Если вы почувствуете, что какая-то асана, которую я предлагаю выполнить, для вас преждевременна, выполните её не очень глубоко, на компромиссном уровне, или вовсе замените её другой асаной - такой, которая приблизительно также включает тело, но проще для вас.</p><p></p><p><strong>3. Ответы на вопросы</strong><br>Каждую неделю (обычно по субботам) я провожу в Zoom групповые онлайн-консультации (вебинары), на которых мы общаемся, поддерживаем мотивацию, обсуждаем возникающие трудности и вопросы. Перед каждой такой консультацией я буду высылать вам письмо с указанием даты и времени её проведения, а также ссылкой для того, чтобы к ней присоединиться. То, что интересно вам, наверняка будет интересно и многим другим. Поэтому, обсуждение вопросов на групповых консультациях наиболее эффективно. Если случится так, что время консультации окажется вам неудобным, в этом случае пришлите ваши вопросы имейлом до её начала. Я отвечу на них на консультации, а вам пришлю ссылку на запись, чтобы вы могли посмотреть её в удобное вам время. Записи консультаций сохраняются в течение одной недели.</p><p></p><p><strong>4. Ваши регулярные действия - условие результатов</strong><br>Хотя это не программа подготовки космонавтов, всё-таки от вас потребуется некоторая дисциплина и целенаправленные действия. Так устроена эта жизнь, что для получения результатов нужно действовать. В том числе нужно действовать, если вы хотите наполнить жизнь творчеством, самовыражением, артисцизмом, свободой... Входите в этот поток и действуйте - выполняйте асаны, пранаяму, медитацию, а также те поведенческие практики, которые вы наметите для себя на первом уроке. И каждое своё действие совершайте, осознавая, что это ваша практика для взращивания этих состояний.</p><p></p><p><strong>5. Первый урок</strong><br>А теперь вы готовы перейти к первому уроку. На этом уроке мы обсудим тему постановки цели на этот месяц и ежедневных действий, которые к ней ведут. А также выполним небольшую практику, которую я рекомендую вам выполнять ежедневно в течение этого месяца. Урок довольно длинный, так как очень важно правильно сформулировать намерение и продумать небольшую практику на каждый день. Так как этот практикум я проводил в прямом эфире, вы услышите мои комментарии и ответы на задаваемые вопросы. Они помогут вам избежать распространённых ошибок.</p><p></p><p>Первый урок ждёт вас в Гармонизаторе, на вкладке &quot;День&quot;.</p><p></p><p>Желаю вам интересного и плодотворного месяца!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png\" alt=\"Месяц свободы\" width=\"504\" height=\"146\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я рад, что вы решились в течение месяца направить внимание и целенаправленно поработать с такими прекрасными состояниями, как творчество, способность создавать поток и действовать в нём, видеть красоту, чувствовать вдохновение, иметь право самовыражаться, проявлять свою уникальность, самобытность, красиво коммунициривать во всех форматах (речь, музыка, рисунок... своё поведение...) - то есть речь о пятой чакре. Внимательно прочитайте это письмо, чтобы эффективно включиться в занятия.</p><p></p><p><strong>1. Расписание совместных практик</strong><br>Первый (вводный) урок уже доступен вам в Гармонизаторе на вкладке &quot;День&quot;. Чтобы его увидеть, при входе в Гармонизатор, укажите тот же ваш имейл, на который пришло данное письмо. Послезавтра вы получите второй урок - это будет наша первая совместная практика. Через неделю вам придёт вторая практика, ещё через неделю - третья, и через неделю - четвёртая. То есть в течение месяца, помимо вводного урока, вас ожидают четыре инереснейшие практики. Доступ к записям всех этих уроков сохранится у вас в течение трёх месяцев после окончания практикума. Тем не менее, я рекомендую вам проходить уроки не откладывая, так чтобы между практиками была неделя для внутренних трансформаций. Не увеличивайте интервалы между практиками, чтобы они не накапливались, как снежный ком. Наиболее эффективный темп занятий - одна практика в неделю. К тому-же имейте в виду, что первый урок посвящён тому, чтобы вы правильно сформулировали намерение на этот месяц, а также сами для себя определили небольшие дополнительные практики, которые будете выполнять каждый день в течение этого месяца.</p><p></p><p><strong>2. Техника безопасности</strong><br>Я забочусь о вашем здоровье и напоминаю, что только вы несёте ответственность за адекватность выполнения асан, пранаям и медитаций, вашим физическим возможностям и психическому состоянию. Важно понимать, что это онлайн занятия, и я не могу проконтролировать ваше состояние. Практикум ориентирован на людей со средним уровнем физической подготовки. Однако, у вам могут быть физические и психологические особенности. Пожалуйста, будьте внимательны к своему состоянию. Если вы почувствуете, что какая-то асана, которую я предлагаю выполнить, для вас преждевременна, выполните её не очень глубоко, на компромиссном уровне, или вовсе замените её другой асаной - такой, которая приблизительно также включает тело, но проще для вас.</p><p></p><p><strong>3. Ответы на вопросы</strong><br>Каждую неделю (обычно по субботам) я провожу в Zoom групповые онлайн-консультации (вебинары), на которых мы общаемся, поддерживаем мотивацию, обсуждаем возникающие трудности и вопросы. Перед каждой такой консультацией я буду высылать вам письмо с указанием даты и времени её проведения, а также ссылкой для того, чтобы к ней присоединиться. То, что интересно вам, наверняка будет интересно и многим другим. Поэтому, обсуждение вопросов на групповых консультациях наиболее эффективно. Если случится так, что время консультации окажется вам неудобным, в этом случае пришлите ваши вопросы имейлом до её начала. Я отвечу на них на консультации, а вам пришлю ссылку на запись, чтобы вы могли посмотреть её в удобное вам время. Записи консультаций сохраняются в течение одной недели.</p><p></p><p><strong>4. Ваши регулярные действия - условие результатов</strong><br>Хотя это не программа подготовки космонавтов, всё-таки от вас потребуется некоторая дисциплина и целенаправленные действия. Так устроена эта жизнь, что для получения результатов нужно действовать. В том числе нужно действовать, если вы хотите наполнить жизнь творчеством, самовыражением, артисцизмом, свободой... Входите в этот поток и действуйте - выполняйте асаны, пранаяму, медитацию, а также те поведенческие практики, которые вы наметите для себя на первом уроке. И каждое своё действие совершайте, осознавая, что это ваша практика для взращивания этих состояний.</p><p></p><p><strong>5. Первый урок</strong><br>А теперь вы готовы перейти к первому уроку. На этом уроке мы обсудим тему постановки цели на этот месяц и ежедневных действий, которые к ней ведут. А также выполним небольшую практику, которую я рекомендую вам выполнять ежедневно в течение этого месяца. Урок довольно длинный, так как очень важно правильно сформулировать намерение и продумать небольшую практику на каждый день. Так как этот практикум я проводил в прямом эфире, вы услышите мои комментарии и ответы на задаваемые вопросы. Они помогут вам избежать распространённых ошибок.</p><p></p><p>Первый урок ждёт вас в Гармонизаторе, на вкладке &quot;День&quot;.</p><p></p><p>Желаю вам интересного и плодотворного месяца!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-freedom-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png","alt":"Месяц свободы","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":154},{"id":"month-freedom-01-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Я рад, что вы решились в течение месяца направить внимание и целенаправленно поработать с такими прекрасными состояниями, как творчество, способность создавать поток и действовать в нём, видеть красоту, чувствовать вдохновение, иметь право самовыражаться, проявлять свою уникальность, самобытность, красиво коммунициривать во всех форматах (речь, музыка, рисунок... своё поведение...) - то есть речь о пятой чакре. Внимательно прочитайте это письмо, чтобы эффективно включиться в занятия.</p><p></p><p><strong>1. Расписание совместных практик</strong><br>Первый (вводный) урок уже доступен вам в Гармонизаторе на вкладке &quot;День&quot;. Чтобы его увидеть, при входе в Гармонизатор, укажите тот же ваш имейл, на который пришло данное письмо. Послезавтра вы получите второй урок - это будет наша первая совместная практика. Через неделю вам придёт вторая практика, ещё через неделю - третья, и через неделю - четвёртая. То есть в течение месяца, помимо вводного урока, вас ожидают четыре инереснейшие практики. Доступ к записям всех этих уроков сохранится у вас в течение трёх месяцев после окончания практикума. Тем не менее, я рекомендую вам проходить уроки не откладывая, так чтобы между практиками была неделя для внутренних трансформаций. Не увеличивайте интервалы между практиками, чтобы они не накапливались, как снежный ком. Наиболее эффективный темп занятий - одна практика в неделю. К тому-же имейте в виду, что первый урок посвящён тому, чтобы вы правильно сформулировали намерение на этот месяц, а также сами для себя определили небольшие дополнительные практики, которые будете выполнять каждый день в течение этого месяца.</p><p></p><p><strong>2. Техника безопасности</strong><br>Я забочусь о вашем здоровье и напоминаю, что только вы несёте ответственность за адекватность выполнения асан, пранаям и медитаций, вашим физическим возможностям и психическому состоянию. Важно понимать, что это онлайн занятия, и я не могу проконтролировать ваше состояние. Практикум ориентирован на людей со средним уровнем физической подготовки. Однако, у вам могут быть физические и психологические особенности. Пожалуйста, будьте внимательны к своему состоянию. Если вы почувствуете, что какая-то асана, которую я предлагаю выполнить, для вас преждевременна, выполните её не очень глубоко, на компромиссном уровне, или вовсе замените её другой асаной - такой, которая приблизительно также включает тело, но проще для вас.</p><p></p><p><strong>3. Ответы на вопросы</strong><br>Каждую неделю (обычно по субботам) я провожу в Zoom групповые онлайн-консультации (вебинары), на которых мы общаемся, поддерживаем мотивацию, обсуждаем возникающие трудности и вопросы. Перед каждой такой консультацией я буду высылать вам письмо с указанием даты и времени её проведения, а также ссылкой для того, чтобы к ней присоединиться. То, что интересно вам, наверняка будет интересно и многим другим. Поэтому, обсуждение вопросов на групповых консультациях наиболее эффективно. Если случится так, что время консультации окажется вам неудобным, в этом случае пришлите ваши вопросы имейлом до её начала. Я отвечу на них на консультации, а вам пришлю ссылку на запись, чтобы вы могли посмотреть её в удобное вам время. Записи консультаций сохраняются в течение одной недели.</p><p></p><p><strong>4. Ваши регулярные действия - условие результатов</strong><br>Хотя это не программа подготовки космонавтов, всё-таки от вас потребуется некоторая дисциплина и целенаправленные действия. Так устроена эта жизнь, что для получения результатов нужно действовать. В том числе нужно действовать, если вы хотите наполнить жизнь творчеством, самовыражением, артисцизмом, свободой... Входите в этот поток и действуйте - выполняйте асаны, пранаяму, медитацию, а также те поведенческие практики, которые вы наметите для себя на первом уроке. И каждое своё действие совершайте, осознавая, что это ваша практика для взращивания этих состояний.</p><p></p><p><strong>5. Первый урок</strong><br>А теперь вы готовы перейти к первому уроку. На этом уроке мы обсудим тему постановки цели на этот месяц и ежедневных действий, которые к ней ведут. А также выполним небольшую практику, которую я рекомендую вам выполнять ежедневно в течение этого месяца. Урок довольно длинный, так как очень важно правильно сформулировать намерение и продумать небольшую практику на каждый день. Так как этот практикум я проводил в прямом эфире, вы услышите мои комментарии и ответы на задаваемые вопросы. Они помогут вам избежать распространённых ошибок.</p><p></p><p>Первый урок ждёт вас в Гармонизаторе, на вкладке &quot;День&quot;.</p><p></p><p>Желаю вам интересного и плодотворного месяца!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-freedom-01','month-freedom',1,0,'Урок 1','[{"type":"video","vimeoId":"1102463072"},{"type":"text","markdown":"ЗАДАНИЕ:\nСформулируйте своё намерение на этот месяц практик, а также определите действия (практики), которые вы будете выполнять ежедневно, несмотря ни на какие непредвиденные затруднения."}]'::jsonb,'aa369f75-e047-535c-a433-9c5d8dcf9366') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('a0566599-ab24-505c-a3e1-90ff1043e248','70547a05-45c5-5e2d-92ed-21217d2420e4','Урок 2',2,0,'{Месяц свободы} Урок 2','{"ru":"{Месяц свободы} Урок 2"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png" alt="Месяц свободы" width="504" height="146" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я надеюсь, что, пройдя первый урок, вы чётко сформулировали намерение на месяц, составили для себя план практик на каждый день, и уже приступили к их выполнению. А значит, вы готовы к первой глубокой исцеляющей практике. Урок уже ждёт вас в Гармонизаторе - на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png\" alt=\"Месяц свободы\" width=\"504\" height=\"146\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я надеюсь, что, пройдя первый урок, вы чётко сформулировали намерение на месяц, составили для себя план практик на каждый день, и уже приступили к их выполнению. А значит, вы готовы к первой глубокой исцеляющей практике. Урок уже ждёт вас в Гармонизаторе - на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-freedom-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png","alt":"Месяц свободы","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":154},{"id":"month-freedom-02-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Я надеюсь, что, пройдя первый урок, вы чётко сформулировали намерение на месяц, составили для себя план практик на каждый день, и уже приступили к их выполнению. А значит, вы готовы к первой глубокой исцеляющей практике. Урок уже ждёт вас в Гармонизаторе - на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-freedom-02','month-freedom',2,2,'Урок 2','[{"type":"video","vimeoId":"1102463103"},{"type":"text","markdown":"ЗАДАНИЕ:\nПродолжайте выполнять те ежедневные практики, которые наметили для себя на первом занятии, а также добавьте работу с телом, составив набор упражнений из того, что мы делали сегодня (при необходимости добавьте что-нибудь от подсказок вашего тела)."}]'::jsonb,'a0566599-ab24-505c-a3e1-90ff1043e248') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('4281828a-d19b-5848-8dd7-607607f55404','70547a05-45c5-5e2d-92ed-21217d2420e4','Урок 3',3,0,'{Месяц свободы} Урок 3','{"ru":"{Месяц свободы} Урок 3"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png" alt="Месяц свободы" width="504" height="146" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Движемся дальше в направлении гармоничного проявления состояний пятой чакры и здоровья органов, психосоматически с ней связанных. Урок ждёт вас в Гармонизаторе - на вкладке &quot;День&quot;.</p><p></p><p>Всех благ!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png\" alt=\"Месяц свободы\" width=\"504\" height=\"146\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Движемся дальше в направлении гармоничного проявления состояний пятой чакры и здоровья органов, психосоматически с ней связанных. Урок ждёт вас в Гармонизаторе - на вкладке &quot;День&quot;.</p><p></p><p>Всех благ!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-freedom-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png","alt":"Месяц свободы","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":154},{"id":"month-freedom-03-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Движемся дальше в направлении гармоничного проявления состояний пятой чакры и здоровья органов, психосоматически с ней связанных. Урок ждёт вас в Гармонизаторе - на вкладке &quot;День&quot;.</p><p></p><p>Всех благ!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-freedom-03','month-freedom',3,7,'Урок 3','[{"type":"video","vimeoId":"1102463144"},{"type":"text","markdown":"ЗАДАНИЕ:\nВ ближайшее время продолжайте осваивать пранаяму и бандхи, которые мы выполняли на практике, а также выполняйте асаны в потоке красоты. Регулярная практика поможет вам превратить новые знания в опыт, и далее в мудрость. А также продолжайте практиковать то, что для вас наиболее ценно из прошлого занятия."}]'::jsonb,'4281828a-d19b-5848-8dd7-607607f55404') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('9e2c1f73-6c32-5c59-b5cc-7a1d709d5186','70547a05-45c5-5e2d-92ed-21217d2420e4','Дополнительная практика',4,0,'{Месяц свободы} Дополнительный урок','{"ru":"{Месяц свободы} Дополнительный урок"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png" alt="Месяц свободы" width="504" height="146" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сюрприз! Чтобы поддержать вас в пространстве свободы и творчества, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию пятой чакры.</p><p></p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p></p><p>Урок уже ждёт вас в Гармонизаторе, на вкладке &quot;День“.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png\" alt=\"Месяц свободы\" width=\"504\" height=\"146\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сюрприз! Чтобы поддержать вас в пространстве свободы и творчества, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию пятой чакры.</p><p></p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p></p><p>Урок уже ждёт вас в Гармонизаторе, на вкладке &quot;День“.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-freedom-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png","alt":"Месяц свободы","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":154},{"id":"month-freedom-04-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Сюрприз! Чтобы поддержать вас в пространстве свободы и творчества, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию пятой чакры.</p><p></p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p></p><p>Урок уже ждёт вас в Гармонизаторе, на вкладке &quot;День“.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-freedom-04','month-freedom',4,3,'Дополнительная практика','[{"type":"video","vimeoId":"1132863767","practiceId":"da40fa29-f4b9-4778-90ba-5ed7067d808f"}]'::jsonb,'9e2c1f73-6c32-5c59-b5cc-7a1d709d5186') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('f1cd2c64-4f9b-5def-804e-f9d4110da98a','70547a05-45c5-5e2d-92ed-21217d2420e4','Урок 4',5,0,'{Месяц свободы} Урок 4','{"ru":"{Месяц свободы} Урок 4"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png" alt="Месяц свободы" width="504" height="146" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Уже прошли три недели программы Месяца свободы. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре.</p><p></p><p>И сейчас перейдите к четвертому уроку. Сразу предупрежу - он длиннее обычного - целых три часа. И важно не прерываться в процессе практики, чтобы не потерять энергетическую нить. Поэтому выберите для этой практики момент, когда у вас будут три часа свободного времени. А также выберите такое место, где вы не будете стесняться прокричаться (и соседей не испугаете). А также приготовьте стаканчик воды, он не помешает. Урок очень плотный. Сначала мы выполним асаны, а затем будем практиковать с энергией букв.</p><p></p><p>Урок ждёт вас в Гармонизаторе, на вкладке &quot;День&quot;.</p><p></p><p>Всех благ!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png\" alt=\"Месяц свободы\" width=\"504\" height=\"146\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Уже прошли три недели программы Месяца свободы. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре.</p><p></p><p>И сейчас перейдите к четвертому уроку. Сразу предупрежу - он длиннее обычного - целых три часа. И важно не прерываться в процессе практики, чтобы не потерять энергетическую нить. Поэтому выберите для этой практики момент, когда у вас будут три часа свободного времени. А также выберите такое место, где вы не будете стесняться прокричаться (и соседей не испугаете). А также приготовьте стаканчик воды, он не помешает. Урок очень плотный. Сначала мы выполним асаны, а затем будем практиковать с энергией букв.</p><p></p><p>Урок ждёт вас в Гармонизаторе, на вкладке &quot;День&quot;.</p><p></p><p>Всех благ!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-freedom-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png","alt":"Месяц свободы","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":154},{"id":"month-freedom-05-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Уже прошли три недели программы Месяца свободы. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре.</p><p></p><p>И сейчас перейдите к четвертому уроку. Сразу предупрежу - он длиннее обычного - целых три часа. И важно не прерываться в процессе практики, чтобы не потерять энергетическую нить. Поэтому выберите для этой практики момент, когда у вас будут три часа свободного времени. А также выберите такое место, где вы не будете стесняться прокричаться (и соседей не испугаете). А также приготовьте стаканчик воды, он не помешает. Урок очень плотный. Сначала мы выполним асаны, а затем будем практиковать с энергией букв.</p><p></p><p>Урок ждёт вас в Гармонизаторе, на вкладке &quot;День&quot;.</p><p></p><p>Всех благ!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-freedom-05','month-freedom',5,4,'Урок 4','[{"type":"video","vimeoId":"1102463196"},{"type":"text","markdown":"ЗАДАНИЕ:\nВ ближайшее время продолжайте практиковать то, что наметили для себя на первом занятии, а также то, что для вас наиболее ценно из всех занятий этого практикума. И хотя бы раз, пройдите весь алфавит, отдавшись этой практике настолько глубоко, насколько можете. То есть, на шепча звуки, боясь кого-то побеспокоить, а полностью им отдаваясь - со смехом, слезами, кашлем, криком, хрипом... - проявляя то, что в вас есть."}]'::jsonb,'f1cd2c64-4f9b-5def-804e-f9d4110da98a') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('a6d2a486-d9eb-533f-80e0-b4698044265e','70547a05-45c5-5e2d-92ed-21217d2420e4','Ещё один дополнительный урок',6,0,'{Месяц свободы} Ещё один дополнительный урок','{"ru":"{Месяц свободы} Ещё один дополнительный урок"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png" alt="Месяц свободы" width="504" height="146" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Высылаю ещё один дополнительный урок, направленный на гармонизацию пятой чакры. Просто, немного другие техники, другие состояния (энергии), другое время...</p><p></p><p>Урок уже ждёт вас в Гармонизаторе, на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png\" alt=\"Месяц свободы\" width=\"504\" height=\"146\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Высылаю ещё один дополнительный урок, направленный на гармонизацию пятой чакры. Просто, немного другие техники, другие состояния (энергии), другое время...</p><p></p><p>Урок уже ждёт вас в Гармонизаторе, на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-freedom-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png","alt":"Месяц свободы","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":154},{"id":"month-freedom-06-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Высылаю ещё один дополнительный урок, направленный на гармонизацию пятой чакры. Просто, немного другие техники, другие состояния (энергии), другое время...</p><p></p><p>Урок уже ждёт вас в Гармонизаторе, на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-freedom-06','month-freedom',6,3,'Ещё один дополнительный урок','[{"type":"video","vimeoId":"1130601826","practiceId":"b1e429fe-03f6-41d1-8ecb-d731af321ff4"}]'::jsonb,'a6d2a486-d9eb-533f-80e0-b4698044265e') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('de955c05-5bff-5e5c-995c-e4dfec7f169b','70547a05-45c5-5e2d-92ed-21217d2420e4','Урок 5',7,0,'{Месяц свободы} Урок 5','{"ru":"{Месяц свободы} Урок 5"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png" alt="Месяц свободы" width="504" height="146" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока месяца практик, направленных на гармонизацию вишудхи. Я надеюсь, вы замечаете результаты выполняемых практик - как на уровне здоровья, так и в виде изменений в жизни, в вашем поведении, в восприятии окружающего вас мира (а может быть вы и в самом деле осознали, что сами создаёте мир, в котором живёте). Закрепитесь на достигнутом, и пойдите ещё дальше в результате практики пятого урока. Она о волшебстве...</p><p></p><p>Урок ждёт вас в Гармонизаторе, на вкладке &quot;День“.</p><p></p><p>И я приглашаю вас в дальнейший путь. За месяц вы очистили и гармонизировали вишудху настолько, насколько это возможно в данное время. И это хороший фундамент для того, чтобы перейти на уровень шестой чакры - аджны (чакры мудрости), и проработать её сферы. Продолжайте движение вперёд, присоединяйтесь к практикам Месяца мудрости. Чтобы ознакомиться с описанием этого практикума, перейдите на страницу - <a href="https://zamkovoi.yoga/m6/">https://zamkovoi.yoga/m6/</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png\" alt=\"Месяц свободы\" width=\"504\" height=\"146\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока месяца практик, направленных на гармонизацию вишудхи. Я надеюсь, вы замечаете результаты выполняемых практик - как на уровне здоровья, так и в виде изменений в жизни, в вашем поведении, в восприятии окружающего вас мира (а может быть вы и в самом деле осознали, что сами создаёте мир, в котором живёте). Закрепитесь на достигнутом, и пойдите ещё дальше в результате практики пятого урока. Она о волшебстве...</p><p></p><p>Урок ждёт вас в Гармонизаторе, на вкладке &quot;День“.</p><p></p><p>И я приглашаю вас в дальнейший путь. За месяц вы очистили и гармонизировали вишудху настолько, насколько это возможно в данное время. И это хороший фундамент для того, чтобы перейти на уровень шестой чакры - аджны (чакры мудрости), и проработать её сферы. Продолжайте движение вперёд, присоединяйтесь к практикам Месяца мудрости. Чтобы ознакомиться с описанием этого практикума, перейдите на страницу - <a href=\"https://zamkovoi.yoga/m6/\">https://zamkovoi.yoga/m6/</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-freedom-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png","alt":"Месяц свободы","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":154},{"id":"month-freedom-07-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока месяца практик, направленных на гармонизацию вишудхи. Я надеюсь, вы замечаете результаты выполняемых практик - как на уровне здоровья, так и в виде изменений в жизни, в вашем поведении, в восприятии окружающего вас мира (а может быть вы и в самом деле осознали, что сами создаёте мир, в котором живёте). Закрепитесь на достигнутом, и пойдите ещё дальше в результате практики пятого урока. Она о волшебстве...</p><p></p><p>Урок ждёт вас в Гармонизаторе, на вкладке &quot;День“.</p><p></p><p>И я приглашаю вас в дальнейший путь. За месяц вы очистили и гармонизировали вишудху настолько, насколько это возможно в данное время. И это хороший фундамент для того, чтобы перейти на уровень шестой чакры - аджны (чакры мудрости), и проработать её сферы. Продолжайте движение вперёд, присоединяйтесь к практикам Месяца мудрости. Чтобы ознакомиться с описанием этого практикума, перейдите на страницу - <a href=\"https://zamkovoi.yoga/m6/\">https://zamkovoi.yoga/m6/</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-freedom-07','month-freedom',7,4,'Урок 5','[{"type":"video","vimeoId":"1102463208"},{"type":"text","markdown":"ЗАДАНИЕ:\nВ оставшиеся дни Месяца свободы практикуйте наиболее эффективные для вас техники этого правтикума, направляя внимание на свойство вишудхи творить волшебство. И продолжайте осознанно жить в потоке энергий вишудхи.\n\n**Что дальше?**"},{"type":"video","vimeoId":"1151886264"},{"type":"text","markdown":"Я надеюсь, что этот месяц практик принёс вам ощутимые результаты. И рекомендую вам не терять волну - продолжайте движение в потоке регулярных практик! Посмотрите видео выше, а также перейдите по ссылкам ниже, чтобы сориентироваться в пространстве возможностей, и выбрать то, что для вас окажется наиболее полезным.\n- Интенсив для 5 чакры: https://zamkovoi.yoga/i5/\n- Курс \"Источник творческой силы\": https://zamkovoi.yoga/yoga5/\n- Практикум \"Месяц мудрости\": https://zamkovoi.yoga/m6/"}]'::jsonb,'de955c05-5bff-5e5c-995c-e4dfec7f169b') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('e375dbfb-b225-5436-8127-49e8ad5117db','70547a05-45c5-5e2d-92ed-21217d2420e4','Завершение практикума',8,0,'{Месяц свободы} Завершение практикума','{"ru":"{Месяц свободы} Завершение практикума"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png" alt="Месяц свободы" width="504" height="146" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Вот и завершился месяц практик, направленных на гармонизацию вишудхи. Я надеюсь, что этот месяц был для вас плодотворен, что вы развили осознанность к состояниям вишудхи, в значительной степени очистили её и гармонизировали, при этом стали более свободным человеком, творческим, коммуникабельным, ярким, самобытным, вдохновенным, и т.д.</p><p></p><p>Так как практикум завершился, я предлагаю на волне благодарности отпустить все те обещания, которые в связи с этим практикумом вы могли давать мне или я давал вам. Они вас поддерживали, но более не нужны и свободны. Если какие-то обещания вы давали сами себе, но не выполнили (например, не практиковали в должной мере), предлагаю вам себя простить, и всё это также отпустить. Вы сделали лучшее, на что способны. Движемся дальше на легке :)</p><p></p><p>И, если вы ещё не записались на практики следующего месяца, направленные на гармонизацию аджны, то вы можете сделать это на странице - <a href="https://zamkovoi.yoga/m6/">https://zamkovoi.yoga/m6/</a></p><p></p><p>Хотя, я не удивлюсь, если вы предпочтёте углубиться в развитие пятой чакры, и запишитесь на соответствующий интенсив или курс. Уж очень интересные плоды находятся на этом уровне :)<br>- Интенсив для 5 чакры: <a href="https://zamkovoi.yoga/i5/">https://zamkovoi.yoga/i5/</a><br>- Курс &quot;Источник творческой силы&quot;: <a href="https://zamkovoi.yoga/yoga5/">https://zamkovoi.yoga/yoga5/</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png\" alt=\"Месяц свободы\" width=\"504\" height=\"146\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Вот и завершился месяц практик, направленных на гармонизацию вишудхи. Я надеюсь, что этот месяц был для вас плодотворен, что вы развили осознанность к состояниям вишудхи, в значительной степени очистили её и гармонизировали, при этом стали более свободным человеком, творческим, коммуникабельным, ярким, самобытным, вдохновенным, и т.д.</p><p></p><p>Так как практикум завершился, я предлагаю на волне благодарности отпустить все те обещания, которые в связи с этим практикумом вы могли давать мне или я давал вам. Они вас поддерживали, но более не нужны и свободны. Если какие-то обещания вы давали сами себе, но не выполнили (например, не практиковали в должной мере), предлагаю вам себя простить, и всё это также отпустить. Вы сделали лучшее, на что способны. Движемся дальше на легке :)</p><p></p><p>И, если вы ещё не записались на практики следующего месяца, направленные на гармонизацию аджны, то вы можете сделать это на странице - <a href=\"https://zamkovoi.yoga/m6/\">https://zamkovoi.yoga/m6/</a></p><p></p><p>Хотя, я не удивлюсь, если вы предпочтёте углубиться в развитие пятой чакры, и запишитесь на соответствующий интенсив или курс. Уж очень интересные плоды находятся на этом уровне :)<br>- Интенсив для 5 чакры: <a href=\"https://zamkovoi.yoga/i5/\">https://zamkovoi.yoga/i5/</a><br>- Курс &quot;Источник творческой силы&quot;: <a href=\"https://zamkovoi.yoga/yoga5/\">https://zamkovoi.yoga/yoga5/</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-freedom-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png","alt":"Месяц свободы","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":154},{"id":"month-freedom-completion-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Вот и завершился месяц практик, направленных на гармонизацию вишудхи. Я надеюсь, что этот месяц был для вас плодотворен, что вы развили осознанность к состояниям вишудхи, в значительной степени очистили её и гармонизировали, при этом стали более свободным человеком, творческим, коммуникабельным, ярким, самобытным, вдохновенным, и т.д.</p><p></p><p>Так как практикум завершился, я предлагаю на волне благодарности отпустить все те обещания, которые в связи с этим практикумом вы могли давать мне или я давал вам. Они вас поддерживали, но более не нужны и свободны. Если какие-то обещания вы давали сами себе, но не выполнили (например, не практиковали в должной мере), предлагаю вам себя простить, и всё это также отпустить. Вы сделали лучшее, на что способны. Движемся дальше на легке :)</p><p></p><p>И, если вы ещё не записались на практики следующего месяца, направленные на гармонизацию аджны, то вы можете сделать это на странице - <a href=\"https://zamkovoi.yoga/m6/\">https://zamkovoi.yoga/m6/</a></p><p></p><p>Хотя, я не удивлюсь, если вы предпочтёте углубиться в развитие пятой чакры, и запишитесь на соответствующий интенсив или курс. Уж очень интересные плоды находятся на этом уровне :)<br>- Интенсив для 5 чакры: <a href=\"https://zamkovoi.yoga/i5/\">https://zamkovoi.yoga/i5/</a><br>- Курс &quot;Источник творческой силы&quot;: <a href=\"https://zamkovoi.yoga/yoga5/\">https://zamkovoi.yoga/yoga5/</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
